const LL mod = 1e9 + 7;
int n;
LL p, k;
set<LL> s;
LL fa[1000100];
int Find(LL x) {
    if(x != fa[x]) return fa[x] = Find(fa[x]);
    return x;
} 

int cnt[1001000];
int main() {
    //freopen("input.txt", "r", stdin);
    cin >> p >> k;
    s.insert(0);
    LL ans = 1;
    if(k==0) {
        for(int i = 1; i < p; i++) ans = ans * p % mod;
        cout << ans;
        return 0;
    }
    for(int i = 0; i < p; i++) fa[i] = i;
    for(int i = 0; i < p; i++) {
        LL shit = k * i % p;
        int x1 = Find(i), x2 = Find(shit);
        fa[x1] = x2;
    }
    for(int i = 0; i < p; i++) {
        int z = Find(i);
        cnt[z]++;
    }
    for(int i = 1; i < p; i++)
        if(cnt[i]) ans = ans * p % mod;
    if(k == 1) ans = ans * p % mod;
    cout << ans;
    return 0;
}
















